-- TRIPSPHERE reference data — attractions (part 2)
INSERT OR IGNORE INTO attractions
(slug, destination_id, name, category, summary, description, image, lat, lng, opening_hours, entry_fee, avg_visit_minutes, rating, reviews_count, is_hidden, unesco, tips) VALUES
('jaisalmer-fort',12,'Jaisalmer Fort','heritage','A living sandstone fort with lanes, temples and havelis inside.','Sonar Quila rises 250 metres above the desert and still houses a few thousand residents. Walk the ramparts at sunset, then explore the Jain temples and the palace museum inside.','/images/jaipur.jpg',26.9124,70.9126,'6:00 AM - 6:00 PM',50,150,4.6,6800,0,1,'Enter from the main gate and climb to the cannon viewpoints.'),
('sam-sand-dunes',12,'Sam Sand Dunes','adventure','Camel rides and jeep safaris on the edge of the Thar.','The dunes are 45 km from town and best at sunset. Camel and jeep rides are arranged on the spot, and desert camps nearby run cultural evenings.','/images/ladakh.jpg',26.8600,70.7000,'3:00 PM - 8:00 PM',0,150,4.3,4200,0,0,'Agree the camel price before mounting; avoid peak holiday crowds.'),
('patwon-ki-haveli',12,'Patwon ki Haveli','heritage','Five connected merchant mansions with filigree stonework.','The most elaborate haveli in Jaisalmer was built for a family of brocade traders. The yellow sandstone facades and tiny balconies are best in low morning light.','/images/jaipur.jpg',26.9167,70.9167,'9:00 AM - 6:00 PM',100,60,4.4,2600,0,0,'Only part of the complex is open; the shop next door has a rooftop view.'),
('dashashwamedh-ghat',13,'Dashashwamedh Ghat Aarti','cultural','The nightly fire ritual on the banks of the Ganga.','Priests perform the Ganga aarti at dusk with lamps, conch shells and bells. Arrive an hour early for a seat on the steps, or watch from a boat on the river.','/images/kerala.jpg',25.3065,83.0106,'5:30 PM - 7:30 PM',0,75,4.7,9200,0,0,'Boats give the clearest view; agree the fare before boarding.'),
('kashi-vishwanath-temple',13,'Kashi Vishwanath Temple','temple','One of the twelve Jyotirlingas, in the heart of the old city.','The temple corridor is now a wide, organised approach through the old lanes. Security is strict and phones are not allowed inside; leave them at your stay.','/images/hampi.jpg',25.3109,83.0107,'3:00 AM - 11:00 PM',0,60,4.7,11500,0,0,'Use the free cloakroom; expect queues before 7 AM.'),
('sarnath',13,'Sarnath','heritage','Where the Buddha gave his first sermon.','The Dhamek Stupa, the ruins of the monastery and the archaeological museum together tell the Buddhist story. The museum holds the famous lion capital.','/images/hampi.jpg',25.3800,83.0250,'6:00 AM - 6:00 PM',300,120,4.5,3600,0,1,'The museum is closed on Fridays; the stupa grounds stay open.'),
('laxman-jhula',14,'Laxman Jhula','cultural','A suspension bridge over the Ganga, lined with cafes and shops.','The bridge is a landmark and a bottleneck: walk it early, then explore the ashrams and cafes on the far bank. The newer Ram Jhula is a quieter crossing.','/images/ladakh.jpg',30.1262,78.3297,'Open all day',0,45,4.3,5400,0,0,'No photographs of the river from the bridge during evening rituals.'),
('triveni-ghat',14,'Triveni Ghat','temple','The main bathing ghat and evening aarti in Rishikesh.','Pilgrims bathe here at dawn, and the evening aarti is smaller and calmer than in Varanasi. Sit on the steps for twenty minutes before dinner.','/images/kerala.jpg',30.1030,78.2900,'4:00 AM - 9:00 PM',0,45,4.4,3900,0,0,'Aarti begins around 6 PM; arrive fifteen minutes early.'),
('rishikesh-rafting',14,'White Water Rafting','adventure','Grade III rapids on the Ganga between Shivpuri and Rishikesh.','Rafting runs 9 to 26 km depending on the stretch, with cliff jumps and calm swims between rapids. Operators provide helmets, life jackets and a safety kayak.','/images/ladakh.jpg',30.1100,78.3200,'7:00 AM - 4:00 PM',1500,180,4.6,7100,0,0,'Choose an operator with a certified guide and working safety gear.'),
('beatles-ashram',14,'Beatles Ashram','heritage','An abandoned ashram covered in street art.','The Maharishi Mahesh Yogi ashram, where the Beatles stayed in 1968, is now a graffiti-covered ruin inside Rajaji forest. Walk the meditation cells and the old lecture hall.','/images/coorg.jpg',30.1200,78.3180,'8:00 AM - 5:00 PM',150,90,4.4,2200,1,0,'Go early for empty halls and better light; carry water.'),
('pangong-tso',15,'Pangong Tso','nature','A high-altitude lake that shifts from blue to turquoise.','The lake sits at 4,350 metres and stretches into Tibet. The drive from Leh takes five hours over Chang La, and an overnight stay is better than a rushed day trip.','/images/ladakh.jpg',33.7500,78.6667,'May - September',0,240,4.8,6400,0,0,'Acclimatise in Leh for two days; carry your own water.'),
('thiksey-monastery',15,'Thiksey Monastery','heritage','A twelve-storey monastery with a 15-metre Buddha.','Morning prayers at 6 AM are open to visitors and worth the early start. The rooftop view over the Indus valley is one of the best in Ladakh.','/images/ladakh.jpg',33.9000,77.7000,'5:00 AM - 6:00 PM',50,90,4.6,3800,0,0,'Dress warmly; the prayer hall is unheated before sunrise.'),
('nubra-valley',15,'Nubra Valley and Diskit','nature','Cold desert dunes, double-humped camels and a cliffside Buddha.','Cross Khardung La to reach Nubra, then continue to Hunder''s dunes and the Maitreya Buddha at Diskit. Two days is the minimum comfortable loop.','/images/ladakh.jpg',34.6000,77.5000,'May - September',0,360,4.6,2900,0,0,'Inner Line Permit required; arrange it in Leh.'),
('magnetic-hill',15,'Magnetic Hill','nature','A gravity-defying stretch of road on the Leh highway.','The optical illusion draws cars onto the highway shoulder, which is not ideal. Treat it as a quick photo stop on the way to Sangam and the Indus-Zanskar confluence.','/images/ladakh.jpg',34.0833,77.4167,'Open all day',0,30,3.9,2100,1,0,'Stay off the road itself; the illusion is best seen from the marked lay-by.'),
('solang-valley',16,'Solang Valley','adventure','Paragliding, zorbing and snow in the winter months.','Solang is an activity hub for Manali, with paragliding and ropeway rides in summer and skiing in winter. Go early to avoid the afternoon rush.','/images/ladakh.jpg',32.3167,77.1500,'8:00 AM - 6:00 PM',0,180,4.2,6800,0,0,'Use registered operators and check weather before flying.'),
('hadimba-temple',16,'Hadimba Temple','temple','A wooden pagoda temple in a cedar forest.','The 16th-century temple is dedicated to Hadimba Devi and sits in a grove of deodar. The carved doorway and the surrounding forest make it a calm hour.','/images/coorg.jpg',32.2432,77.1790,'8:00 AM - 6:00 PM',0,45,4.4,5900,0,0,'Combine with the nearby Manu Temple on foot.'),
('old-manali',16,'Old Manali','cultural','Riverside cafes, orchards and a slower side of town.','Cross the bridge and the pace changes: small bakeries, live music and guesthouses among apple trees. It is a good base for a couple of nights.','/images/coorg.jpg',32.2500,77.1700,'Open all day',0,120,4.3,2400,1,0,'Walk down to the river for the quietest cafes.'),
('jogini-falls',16,'Jogini Falls','waterfall','A short trek to a forest waterfall above the river.','The trail starts near Vashisht and climbs through terraced fields to the falls. It takes about an hour each way and is best after the monsoon.','/images/coorg.jpg',32.2500,77.1900,'7:00 AM - 5:00 PM',0,150,4.3,1300,1,0,'Slippery near the water; go with a local guide if unsure of the path.'),
('tiger-hill',17,'Tiger Hill Sunrise Point','nature','The classic Darjeeling sunrise over Kanchenjunga.','Leave at 4 AM for the viewpoint and hope for a clear morning. On good days the Kanchenjunga range glows before the sun clears the ridge.','/images/munnar.jpg',27.0000,88.2667,'4:00 AM - 7:00 AM',50,90,4.3,7800,0,0,'Skip on cloudy days; your host will know by 4 AM.'),
('darjeeling-himalayan-railway',17,'Darjeeling Himalayan Railway','heritage','The UNESCO-listed toy train through the hills.','The steam-hauled joy ride from Darjeeling to Ghum takes about two hours and crosses the Batasia Loop. Book ahead in season.','/images/munnar.jpg',27.0410,88.2620,'Joy rides 9:00 AM and 1:00 PM',1500,120,4.4,4100,0,1,'Sit on the left for the valley views; windows are open.'),
('batasia-loop',17,'Batasia Loop','heritage','A spiral railway loop with a war memorial and garden.','The loop lets the toy train climb a steep gradient in a full circle. The garden is a pleasant stop, with the Kanchenjunga range behind.','/images/munnar.jpg',27.0167,88.2500,'8:00 AM - 5:00 PM',20,40,4.1,2500,0,0,'Time your visit with the joy train for the classic photograph.'),
('happy-valley-tea-estate',17,'Happy Valley Tea Estate','cultural','A working tea garden and factory above the town.','The tour explains plucking, withering and rolling, and ends with a tasting. Harvest season from March to November shows the factory at full speed.','/images/munnar.jpg',27.0500,88.2667,'9:00 AM - 4:00 PM',150,60,4.2,1600,0,0,'Book the factory walk a day ahead during plucking season.'),
('promenade-beach',18,'Promenade Beach','beach','A rocky seafront promenade with colonial landmarks.','The promenade is closed to traffic in the evening, when the town walks the sea wall past the Gandhi statue and the lighthouse. It is a fifteen-minute stroll with excellent sea air.','/images/goa.jpg',11.9310,79.8360,'Open all day',0,45,4.3,5100,0,0,'Vehicle-free from 6 PM; the rocks are slippery after rain.'),
('aurovilla-matrimandir',18,'Auroville Matrimandir','cultural','A golden meditation sphere at the centre of Auroville.','Viewing the Matrimandir requires a free pass from the visitor centre, and the inner chamber is open only to those who book a meditation slot. The surrounding gardens are open to all.','/images/coorg.jpg',12.0069,79.8106,'9:00 AM - 5:30 PM',0,90,4.4,3300,0,0,'Book the viewing pass online a day ahead; carry ID.'),
('white-town',18,'White Town French Quarter','cultural','Mustard-yellow villas, bakeries and quiet grid streets.','White Town is best on a bicycle in the early morning. The streets between the promenade and the canal hold the best-preserved colonial buildings and a growing number of small galleries.','/images/food.jpg',11.9310,79.8300,'Open all day',0,120,4.5,2900,1,0,'Rent a cycle from a local shop; parking is difficult in the lanes.'),
('shore-temple',19,'Shore Temple','heritage','A 7th-century granite temple facing the Bay of Bengal.','The Shore Temple is the defining image of Mahabalipuram, with its twin towers eroded by salt and wind. Visit at sunrise when the light comes off the water.','/images/hampi.jpg',12.6165,80.1994,'6:00 AM - 6:00 PM',40,60,4.5,6200,0,1,'Sunrise entry is quiet; the ticket also covers the other monuments.'),
('pancha-rathas',19,'Pancha Rathas','heritage','Five monolithic temples carved from single boulders.','Each ratha has a different roof form, a catalogue of early Dravidian architecture. The site is small but needs time to look closely at the carvings.','/images/hampi.jpg',12.6088,80.1986,'6:00 AM - 6:00 PM',40,60,4.5,3800,0,1,'The same ticket as the Shore Temple; keep it.'),
('arjunas-penance',19,'Arjuna''s Penance','heritage','A giant bas-relief carved into a living rock face.','The relief shows a scene from the Mahabharata and is one of the largest open-air carvings in the world. It sits beside the Krishna Mandapam and the boulder field.','/images/hampi.jpg',12.6117,80.1927,'6:00 AM - 6:00 PM',0,30,4.3,1900,0,1,'Combine with the Butter Ball boulder a short walk away.'),
('elephant-falls',20,'Elephant Falls','waterfall','A three-tiered waterfall a short drive from Shillong.','The falls drop through fern-covered rocks and are reached by a stepped path. Water volume peaks in monsoon, when the lower steps close.','/images/coorg.jpg',25.5411,91.8560,'8:00 AM - 5:00 PM',20,45,4.1,4200,0,0,'Wear grippy shoes; the steps stay wet.'),
('umiam-lake',20,'Umiam Lake','nature','A wide reservoir ringed by pine hills.','Umiam is a good half-day stop on the way to Shillong, with kayaking and lakeside viewpoints. The water is calm in winter and the light is best in the late afternoon.','/images/coorg.jpg',25.6700,91.9000,'Open all day',0,90,4.3,3100,0,0,'Kayak operators close by 4 PM; check safety equipment.'),
('mawphlang-sacred-grove',20,'Mawphlang Sacred Grove','nature','A protected forest held sacred by the Khasi community.','A local guide walks you through the grove, explaining the medicinal plants and the rituals that protect it. It is a genuine living conservation practice, not a display.','/images/coorg.jpg',25.4500,91.7500,'9:00 AM - 4:00 PM',200,90,4.6,890,1,0,'A local guide is required; do not pick plants or leave litter.'),
('laitlum-canyons',20,'Laitlum Canyons','nature','Grassland cliffs above a deep green valley.','Laitlum means the end of the hills. The plateau drops away into a valley of terraced fields, and the walk along the rim takes about an hour.','/images/coorg.jpg',25.4500,91.9500,'Open all day',0,90,4.5,1400,1,0,'Go before noon for clear views; the road is narrow at the end.'),
('radhanagar-beach',21,'Radhanagar Beach','beach','One of Asia''s best beaches, with white sand and clear water.','Radhanagar curves for two kilometres under a canopy of mahua trees. The water is calm in season, and the sunset from the northern end is the island''s signature moment.','/images/goa.jpg',11.9833,92.9500,'Open all day',0,180,4.7,6900,0,0,'No vendors on the beach; carry water and leave before dark.'),
('elephant-beach',21,'Elephant Beach','beach','A snorkelling beach reached by boat or forest trail.','Elephant Beach has the best accessible reef in Havelock, with glass-bottom boats and snorkelling trips from Havelock jetty. The forest trail is closed in monsoon.','/images/goa.jpg',12.0333,92.9833,'7:00 AM - 4:00 PM',0,150,4.4,2200,1,0,'Book snorkelling through a licensed operator; reef shoes help.'),
('neil-island',21,'Neil Island Day Trip','nature','A slower island with natural rock bridges and shallow reefs.','Neil (Shaheed Dweep) is a short ferry from Havelock and makes an easy day trip. The natural bridge at Laxmanpur and the Bharatpur snorkelling point are the highlights.','/images/goa.jpg',11.8333,93.0500,'Ferries 8:00 AM - 4:00 PM',1000,300,4.5,2600,0,0,'Book the return ferry before leaving; the last boat is early.');
